function Header({ count, user, onLogout }) {
  const {language,t,openLanguageDialog}=useContext(LanguageContext);
  const location=useLocation();
  const [mobileMenuOpen,setMobileMenuOpen]=useState(false);
  const onAccountPage=location.pathname.startsWith('/account');
  const showPublicMobileMenu=!(user && onAccountPage);
  useEffect(()=>setMobileMenuOpen(false),[location.pathname,user?.id]);
  return <><div className="announcement"><span>{t('Secure precious metals marketplace · worldwide delivery preview')}</span><span className="announcement-right">{t('Worldwide')} <i>·</i> USD $</span></div><header className="header"><Link className="brand" to="/"><span className="brand-mark">G</span><span>GOLD <b>INVESTMENT</b></span></Link><nav className={`header-public-nav${showPublicMobileMenu?'':' account-dashboard-public-nav-hidden'}`} aria-label="Main navigation"><NavLink to="/shop">{t('Buy Metals')}</NavLink><NavLink to="/sell">{t('Sell metals')}</NavLink><NavLink to="/prices">{t('Prices')}</NavLink><NavLink to="/how-it-works">{t('How it works')}</NavLink><button className={`mobile-menu-toggle${mobileMenuOpen?' is-open':''}`} type="button" aria-label={mobileMenuOpen?'Close menu':'Open menu'} aria-expanded={mobileMenuOpen} aria-controls="mobile-public-menu" onClick={()=>setMobileMenuOpen(open=>!open)}><span className="menu-icon" aria-hidden="true"><i/><i/><i/></span></button><ol id="mobile-public-menu" className={`mobile-public-menu${mobileMenuOpen?' is-open':''}`} inert={!mobileMenuOpen}>{[['/shop','Buy Metals'],['/sell','Sell Metals'],['/prices','Prices'],['/how-it-works','How It Works']].map(([to,label])=><li key={to}><Link to={to} onClick={()=>setMobileMenuOpen(false)}>{t(label)}</Link></li>)}</ol></nav><div className="head-actions">{user?<><Link className="account-chip" to="/account">{user.name.split(' ')[0]}{user.identityVerified===true&&<i className="verification-mark is-verified" title="Identity verified" aria-label="Verified account">✓</i>}</Link><button className="link-button" onClick={onLogout}>{t('Sign out')}</button></>:<Link className="account-chip" to="/login">{t('Sign in')}</Link>}<Link className="cart-button" to="/cart">{t('Bag')} <span>{count}</span></Link><button className="language-trigger" type="button" onClick={openLanguageDialog} aria-label={t('Language')}>{language==='ar-SA'?'عربي':'EN'}</button></div></header></>;
}
