function LanguageChooser({language,onSelect,t}) {
  const [choice,setChoice]=useState(language);
  useEffect(()=>setChoice(language),[language]);
  return <div className="language-backdrop" role="presentation"><section className="language-dialog" role="dialog" aria-modal="true" aria-labelledby="language-title" dir={choice==='ar-SA'?'rtl':'ltr'}><span className="language-globe" aria-hidden="true">◎</span><div className="eyebrow">GOLD INVESTMENT · GLOBAL</div><h2 id="language-title">{t('Choose your language')}</h2><p>{t('Your language is saved on this device.')}</p><div className="language-options"><button type="button" className={choice==='ar-SA'?'chosen':''} onClick={()=>setChoice('ar-SA')}><span>🇸🇦</span><b>العربية</b><small>{t('Arabic (Saudi Arabia)')}</small><i>{choice==='ar-SA'?'✓':''}</i></button><button type="button" className={choice==='en-US'?'chosen':''} onClick={()=>setChoice('en-US')}><span>🇺🇸</span><b>English</b><small>United States</small><i>{choice==='en-US'?'✓':''}</i></button></div><button type="button" className="button button-gold language-continue" onClick={()=>onSelect(choice)}>{t('Continue')} <span>→</span></button></section></div>;
}
function ProductArt({ product }) {
  const silver = product.metal === 'silver';
  const photoIds = {
    'gold-coin': '8442429',
    'gold-bar': '29336321',
    'gold-half': '8442342',
    'silver-bar': '20979927',
    'silver-coin': '8442431',
    'silver-five': '20979923'
  };
  const photoId = photoIds[product.image];
  const photoUrl = `https://images.pexels.com/photos/${photoId}/pexels-photo-${photoId}.jpeg?auto=compress&cs=tinysrgb&w=1200`;
  return <div className={`product-image ${silver ? 'silver-bg' : 'gold-bg'}`}>
    <img src={photoUrl} alt={`Representative photo of ${product.weightOz} troy oz ${product.metal} ${product.type.toLowerCase()} bullion`} loading="lazy" onError={event => { event.currentTarget.style.display = 'none'; }}/>
    <span className="badge">{product.badge}</span>
    <span className="product-weight-tag">{product.weightOz} troy oz</span>
    <span className="product-render-tag">Representative bullion photo · design may vary</span>
  </div>;
}
function ProductCard({ product }) {
  const { add } = useContext(CartContext);
  return <article className="product-card"><Link to={`/products/${product.slug}`}><ProductArt product={product}/></Link><div className="card-details"><div className="card-meta"><span>{product.metal} · {product.type}</span><span>{product.weightOz} troy oz</span></div><h3><Link to={`/products/${product.slug}`}>{product.name}</Link></h3><div className="purity">{product.purity}</div><div className="card-bottom"><div className="price-block"><small>{product.priceSource?.includes('live spot')?'LIVE SPOT · PREMIUM INCLUDED':'MOCK PRICE · PREMIUM INCLUDED'}</small><b>{format(product.priceCents)}</b></div><button className="add-button" disabled={product.stock===0} onClick={() => add(product)} aria-label={`Add ${product.name} to cart`}>+</button></div><div className={`stock ${product.stock===0?'out-of-stock':''}`}>{product.stock>0?`${product.stock} available · ${product.stock<10?'limited':'in stock'}`:'Currently unavailable'}</div><div className="product-options-line"><span>Insured delivery options</span><span>Vault request available</span></div></div></article>;
}
function ProductGrid({ products }) { return <div className="product-grid">{products.map(p => <ProductCard key={p.id} product={p}/>)}</div>; }
